const getMatchByRoomID = `-- name: GetMatchByRoomID :many
SELECT id, room_id, state, version, mode, difficulty, error_preset, hints_enabled, auto_remove_notes, rule_version, puzzle_id, puzzle_revision, transformation_seed, puzzle_difficulty, generator_version, solver_version, started_at_ms, completed_at_ms, result_reason, elapsed_ms, assisted, created_at_ms FROM matches WHERE room_id = ? ORDER BY created_at_ms DESC
`

func (q *Queries) GetMatchByRoomID(ctx context.Context, roomID string) ([]Match, error) {
	rows, err := q.db.QueryContext(ctx, getMatchByRoomID, roomID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Match{}
	for rows.Next() {
		var i Match
		if err := rows.Scan(
			&i.ID,
			&i.RoomID,
			&i.State,
			&i.Version,
			&i.Mode,
			&i.Difficulty,
			&i.ErrorPreset,
			&i.HintsEnabled,
			&i.AutoRemoveNotes,
			&i.RuleVersion,
			&i.PuzzleID,
			&i.PuzzleRevision,
			&i.TransformationSeed,
			&i.PuzzleDifficulty,
			&i.GeneratorVersion,
			&i.SolverVersion,
			&i.StartedAtMs,
			&i.CompletedAtMs,
			&i.ResultReason,
			&i.ElapsedMs,
			&i.Assisted,
			&i.CreatedAtMs,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

